117: func (c *Session) ListSharenames() ([]string, error) {
118: 	servername := c.addr
119: 
120: 	fs, err := c.Mount(fmt.Sprintf(`\\%s\IPC$`, servername))
121: 	if err != nil {
122: 		return nil, err
123: 	}
124: 	defer fs.Umount()
125: 
126: 	fs = fs.WithContext(c.ctx)
127: 
128: 	f, err := fs.OpenFile("srvsvc", os.O_RDWR, 0666)
129: 	if err != nil {
130: 		return nil, err
131: 	}
132: 	defer f.Close()
133: 
134: 	callId := rand.Uint32()
135: 
136: 	bindReq := &IoctlRequest{
137: 		CtlCode:           FSCTL_PIPE_TRANSCEIVE,
138: 		OutputOffset:      0,
139: 		OutputCount:       0,
140: 		MaxInputResponse:  0,
141: 		MaxOutputResponse: 4280,
142: 		Flags:             SMB2_0_IOCTL_IS_FSCTL,
143: 		Input: &msrpc.Bind{
144: 			CallId: callId,
145: 		},
146: 	}
147: 
148: 	output, err := f.ioctl(bindReq)
149: 	if err != nil {
150: 		return nil, &os.PathError{Op: "listSharenames", Path: f.name, Err: err}
151: 	}
152: 
153: 	r1 := msrpc.BindAckDecoder(output)
154: 	if r1.IsInvalid() || r1.CallId() != callId {
155: 		return nil, &os.PathError{Op: "listSharenames", Path: f.name, Err: &InvalidResponseError{"broken bind ack response format"}}
156: 	}
157: 
158: 	callId++
159: 
160: 	reqReq := &IoctlRequest{
161: 		CtlCode:          FSCTL_PIPE_TRANSCEIVE,
162: 		OutputOffset:     0,
163: 		OutputCount:      0,
164: 		MaxInputResponse: 0,
165: 		// MaxOutputResponse: 4280,
166: 		MaxOutputResponse: 1024,
167: 		Flags:             SMB2_0_IOCTL_IS_FSCTL,
168: 		Input: &msrpc.NetShareEnumAllRequest{
169: 			CallId:     callId,
170: 			ServerName: servername,
171: 			Level:      1, // level 1 seems to be portable
172: 		},
173: 	}
174: 
175: 	output, err = f.ioctl(reqReq)
176: 	if err != nil {
177: 		if rerr, ok := err.(*ResponseError); ok && NtStatus(rerr.Code) == STATUS_BUFFER_OVERFLOW {
178: 			buf := make([]byte, 4280)
179: 
180: 			rlen := 4280 - len(output)
181: 
182: 			n, err := f.readAt(buf[:rlen], 0)
183: 			if err != nil {
184: 				return nil, &os.PathError{Op: "listSharenames", Path: f.name, Err: err}
185: 			}
186: 
187: 			output = append(output, buf[:n]...)
188: 
189: 			r2 := msrpc.NetShareEnumAllResponseDecoder(output)
190: 			if r2.IsInvalid() || r2.CallId() != callId {
191: 				return nil, &os.PathError{Op: "listSharenames", Path: f.name, Err: &InvalidResponseError{"broken net share enum response format"}}
192: 			}
193: 
194: 			for r2.IsIncomplete() {
195: 				n, err := f.readAt(buf, 0)
196: 				if err != nil {
197: 					return nil, &os.PathError{Op: "listSharenames", Path: f.name, Err: err}
198: 				}
199: 
200: 				r3 := msrpc.NetShareEnumAllResponseDecoder(buf[:n])
201: 				if r3.IsInvalid() || r3.CallId() != callId {
202: 					return nil, &os.PathError{Op: "listSharenames", Path: f.name, Err: &InvalidResponseError{"broken net share enum response format"}}
203: 				}
204: 
205: 				output = append(output, r3.Buffer()...)
206: 
207: 				r2 = msrpc.NetShareEnumAllResponseDecoder(output)
208: 			}
209: 
210: 			return r2.ShareNameList(), nil
211: 		}
212: 
213: 		return nil, &os.PathError{Op: "listSharenames", Path: f.name, Err: err}
214: 	}
215: 
216: 	r2 := msrpc.NetShareEnumAllResponseDecoder(output)
217: 	if r2.IsInvalid() || r2.IsIncomplete() || r2.CallId() != callId {
218: 		return nil, &os.PathError{Op: "listSharenames", Path: f.name, Err: &InvalidResponseError{"broken net share enum response format"}}
219: 	}
220: 
221: 	return r2.ShareNameList(), nil
222: }
