249: func (fs *Share) newFile(r CreateResponseDecoder, name string) *File {
250: 	fd := r.FileId().Decode()
251: 
252: 	fileStat := &FileStat{
253: 		CreationTime:   time.Unix(0, r.CreationTime().Nanoseconds()),
254: 		LastAccessTime: time.Unix(0, r.LastAccessTime().Nanoseconds()),
255: 		LastWriteTime:  time.Unix(0, r.LastWriteTime().Nanoseconds()),
256: 		ChangeTime:     time.Unix(0, r.ChangeTime().Nanoseconds()),
257: 		EndOfFile:      r.EndofFile(),
258: 		AllocationSize: r.AllocationSize(),
259: 		FileAttributes: r.FileAttributes(),
260: 		FileName:       base(name),
261: 	}
262: 
263: 	f := &File{fs: fs, fd: fd, name: name, fileStat: fileStat}
264: 
265: 	runtime.SetFinalizer(f, (*File).close)
266: 
267: 	return f
268: }
