352: 		SmbCreateFlags:       0,
353: 		DesiredAccess:        FILE_WRITE_ATTRIBUTES,
354: 		FileAttributes:       FILE_ATTRIBUTE_NORMAL,
355: 		ShareAccess:          FILE_SHARE_READ | FILE_SHARE_WRITE,
