442: func (fs *Share) remove(name string) error {
443: 	name = normPath(name)
444: 
445: 	if err := validatePath("remove", name, false); err != nil {
446: 		return err
447: 	}
448: 
449: 	req := &CreateRequest{
450: 		SecurityFlags:        0,
451: 		RequestedOplockLevel: SMB2_OPLOCK_LEVEL_NONE,
452: 		ImpersonationLevel:   Impersonation,
453: 		SmbCreateFlags:       0,
454: 		DesiredAccess:        DELETE,
455: 		FileAttributes:       0,
456: 		ShareAccess:          FILE_SHARE_DELETE,
457: 		CreateDisposition:    FILE_OPEN,
458: 		// CreateOptions:        FILE_OPEN_REPARSE_POINT | FILE_DELETE_ON_CLOSE,
459: 		CreateOptions: FILE_OPEN_REPARSE_POINT,
460: 	}
461: 	// FILE_DELETE_ON_CLOSE doesn't work for reparse point, so use FileDispositionInformation instead
462: 
463: 	f, err := fs.createFile(name, req, false)
464: 	if err != nil {
465: 		return &os.PathError{Op: "remove", Path: name, Err: err}
466: 	}
467: 
468: 	err = f.remove()
469: 	if e := f.close(); err == nil {
470: 		err = e
471: 	}
472: 	if err != nil {
473: 		return &os.PathError{Op: "remove", Path: name, Err: err}
474: 	}
475: 
476: 	return nil
477: }
