479: func (fs *Share) Rename(oldpath, newpath string) error {
480: 	oldpath = normPath(oldpath)
481: 	newpath = normPath(newpath)
482: 
483: 	if err := validatePath("rename from", oldpath, false); err != nil {
484: 		return err
485: 	}
486: 
487: 	if err := validatePath("rename to", newpath, false); err != nil {
488: 		return err
489: 	}
490: 
491: 	create := &CreateRequest{
492: 		SecurityFlags:        0,
493: 		RequestedOplockLevel: SMB2_OPLOCK_LEVEL_NONE,
494: 		ImpersonationLevel:   Impersonation,
495: 		SmbCreateFlags:       0,
496: 		DesiredAccess:        DELETE,
497: 		FileAttributes:       FILE_ATTRIBUTE_NORMAL,
498: 		ShareAccess:          FILE_SHARE_DELETE,
499: 		CreateDisposition:    FILE_OPEN,
500: 		CreateOptions:        FILE_OPEN_REPARSE_POINT,
501: 	}
502: 
503: 	f, err := fs.createFile(oldpath, create, false)
504: 	if err != nil {
505: 		return &os.LinkError{Op: "rename", Old: oldpath, New: newpath, Err: err}
506: 	}
507: 
508: 	info := &SetInfoRequest{
509: 		FileInfoClass:         FileRenameInformation,
510: 		AdditionalInformation: 0,
511: 		Input: &FileRenameInformationType2Encoder{
512: 			ReplaceIfExists: 0,
513: 			RootDirectory:   0,
514: 			FileName:        newpath,
515: 		},
516: 	}
517: 
518: 	err = f.setInfo(info)
519: 	if e := f.close(); err == nil {
520: 		err = e
521: 	}
522: 	if err != nil {
523: 		return &os.LinkError{Op: "rename", Old: oldpath, New: newpath, Err: err}
524: 	}
525: 	return nil
526: }
