528: // Symlink mimics os.Symlink.
529: // This API should work on latest Windows and latest MacOS.
530: // However it may not work on Linux because Samba doesn't support reparse point well.
531: // Also there is a restriction on target pathname.
532: // Generally, a pathname begins with leading backslash (e.g `\dir\name`) can be interpreted as two ways.
533: // On windows, it is evaluated as a relative path, on other systems, it is evaluated as an absolute path.
534: // This implementation always assumes that format is absolute path.
535: // So, if you know the target server is Windows, you should avoid that format.
536: // If you want to use an absolute target path on windows, you can use // `C:\dir\name` format instead.
537: func (fs *Share) Symlink(target, linkpath string) error {
538: 	target = normPath(target)
539: 	linkpath = normPath(linkpath)
540: 
541: 	if err := validatePath("symlink target", target, true); err != nil {
542: 		return err
543: 	}
544: 
545: 	if err := validatePath("symlink linkpath", linkpath, false); err != nil {
546: 		return err
547: 	}
548: 
549: 	rdbuf := new(SymbolicLinkReparseDataBuffer)
550: 
551: 	if len(target) >= 2 && target[1] == ':' {
552: 		if len(target) == 2 {
553: 			return os.ErrInvalid
554: 		}
555: 
556: 		if target[2] != '\\' {
557: 			rdbuf.Flags = SYMLINK_FLAG_RELATIVE
558: 		}
559: 		rdbuf.SubstituteName = `\??\` + target
560: 		rdbuf.PrintName = rdbuf.SubstituteName[4:]
561: 	} else {
562: 		if target[0] != '\\' {
563: 			rdbuf.Flags = SYMLINK_FLAG_RELATIVE // It's not true on window server.
564: 		}
565: 		rdbuf.SubstituteName = target
566: 		rdbuf.PrintName = rdbuf.SubstituteName
567: 	}
568: 
569: 	create := &CreateRequest{
570: 		SecurityFlags:        0,
571: 		RequestedOplockLevel: SMB2_OPLOCK_LEVEL_NONE,
572: 		ImpersonationLevel:   Impersonation,
573: 		SmbCreateFlags:       0,
574: 		DesiredAccess:        FILE_WRITE_ATTRIBUTES | DELETE,
575: 		FileAttributes:       FILE_ATTRIBUTE_REPARSE_POINT,
576: 		ShareAccess:          FILE_SHARE_READ | FILE_SHARE_WRITE,
577: 		CreateDisposition:    FILE_CREATE,
578: 		CreateOptions:        FILE_OPEN_REPARSE_POINT,
579: 	}
580: 
581: 	f, err := fs.createFile(linkpath, create, false)
582: 	if err != nil {
583: 		return &os.LinkError{Op: "symlink", Old: target, New: linkpath, Err: err}
584: 	}
585: 
586: 	req := &IoctlRequest{
587: 		CtlCode:           FSCTL_SET_REPARSE_POINT,
588: 		OutputOffset:      0,
589: 		OutputCount:       0,
590: 		MaxInputResponse:  0,
591: 		MaxOutputResponse: 0,
592: 		Flags:             SMB2_0_IOCTL_IS_FSCTL,
593: 		Input:             rdbuf,
594: 	}
595: 
596: 	_, err = f.ioctl(req)
597: 	if err != nil {
598: 		f.remove()
599: 		f.close()
600: 
601: 		return &os.PathError{Op: "symlink", Path: f.name, Err: err}
602: 	}
603: 
604: 	err = f.close()
605: 	if err != nil {
606: 		return &os.PathError{Op: "symlink", Path: f.name, Err: err}
607: 	}
608: 
609: 	return nil
