980: func evalSymlinkError(name string, errData []byte) (string, error) {
981: 	d := SymbolicLinkErrorResponseDecoder(errData)
982: 	if d.IsInvalid() {
983: 		return "", &InvalidResponseError{"broken symbolic link error response format"}
984: 	}
985: 
986: 	ud, u := d.SplitUnparsedPath(name)
987: 	if ud == "" && u == "" {
988: 		return "", &InvalidResponseError{"broken symbolic link error response format"}
989: 	}
990: 
991: 	target := d.SubstituteName()
992: 
993: 	switch {
994: 	case strings.HasPrefix(target, `\??\UNC\`):
995: 		target = `\\` + target[8:]
996: 	case strings.HasPrefix(target, `\??\`):
997: 		target = target[4:]
998: 	}
999: 
1000: 	if d.Flags()&SYMLINK_FLAG_RELATIVE == 0 {
1001: 		return target + u, nil
1002: 	}
1003: 
1004: 	return dir(ud) + target + u, nil
1005: }
