1693: func copyBuffer(r io.Reader, w io.Writer, buf []byte) (n int64, err error) {
1694: 	for {
1695: 		nr, er := r.Read(buf)
1696: 		if nr > 0 {
1697: 			nw, ew := w.Write(buf[:nr])
1698: 			if nw > 0 {
1699: 				n += int64(nw)
1700: 			}
1701: 			if ew != nil {
1702: 				err = ew
1703: 				break
1704: 			}
1705: 			if nr != nw {
1706: 				err = io.ErrShortWrite
1707: 				break
1708: 			}
1709: 		}
1710: 		if er != nil {
1711: 			if er != io.EOF {
1712: 				err = er
1713: 			}
1714: 			break
1715: 		}
1716: 	}
1717: 	return
1718: }
