1720: func (f *File) copyTo(wf *File) (supported bool, n int64, err error) {
1721: 	f.m.Lock()
1722: 	defer f.m.Unlock()
1723: 
1724: 	req := &IoctlRequest{
1725: 		CtlCode:           FSCTL_SRV_REQUEST_RESUME_KEY,
1726: 		OutputOffset:      0,
1727: 		OutputCount:       0,
1728: 		MaxInputResponse:  0,
1729: 		MaxOutputResponse: 32,
1730: 		Flags:             SMB2_0_IOCTL_IS_FSCTL,
1731: 	}
1732: 
1733: 	output, err := f.ioctl(req)
1734: 	if err != nil {
1735: 		if rerr, ok := err.(*ResponseError); ok && NtStatus(rerr.Code) == STATUS_NOT_SUPPORTED {
1736: 			return false, -1, nil
1737: 		}
1738: 
1739: 		return true, -1, &os.LinkError{Op: "copy", Old: f.name, New: wf.name, Err: err}
1740: 
1741: 	}
1742: 
1743: 	sr := SrvRequestResumeKeyResponseDecoder(output)
1744: 	if sr.IsInvalid() {
1745: 		return true, -1, &os.LinkError{Op: "copy", Old: f.name, New: wf.name, Err: &InvalidResponseError{"broken srv request resume key response format"}}
1746: 	}
1747: 
1748: 	off, err := f.seek(0, io.SeekCurrent)
1749: 	if err != nil {
1750: 		return true, -1, &os.LinkError{Op: "copy", Old: f.name, New: wf.name, Err: err}
1751: 	}
1752: 
1753: 	end, err := f.seek(0, io.SeekEnd)
1754: 	if err != nil {
1755: 		return true, -1, &os.LinkError{Op: "copy", Old: f.name, New: wf.name, Err: err}
1756: 	}
1757: 
1758: 	woff, err := wf.seek(0, io.SeekCurrent)
1759: 	if err != nil {
1760: 		return true, -1, &os.LinkError{Op: "copy", Old: f.name, New: wf.name, Err: err}
1761: 	}
1762: 
1763: 	var chunks []*SrvCopychunk
1764: 
1765: 	remains := end
1766: 
1767: 	for {
1768: 		const maxChunkSize = 1024 * 1024
1769: 		const maxTotalSize = 16 * 1024 * 1024
1770: 		// https://msdn.microsoft.com/en-us/library/cc512134(v=vs.85).aspx
1771: 
1772: 		if remains < maxTotalSize {
1773: 			nchunks := remains / maxChunkSize
1774: 
1775: 			chunks = make([]*SrvCopychunk, nchunks, nchunks+1)
1776: 			for i := range chunks {
1777: 				chunks[i] = &SrvCopychunk{
1778: 					SourceOffset: off + int64(i)*maxChunkSize,
1779: 					TargetOffset: woff + int64(i)*maxChunkSize,
1780: 					Length:       maxChunkSize,
1781: 				}
1782: 			}
1783: 
1784: 			remains %= maxChunkSize
1785: 			if remains != 0 {
1786: 				chunks = append(chunks, &SrvCopychunk{
1787: 					SourceOffset: off + int64(nchunks)*maxChunkSize,
1788: 					TargetOffset: woff + int64(nchunks)*maxChunkSize,
1789: 					Length:       uint32(remains),
1790: 				})
1791: 				remains = 0
1792: 			}
1793: 		} else {
1794: 			chunks = make([]*SrvCopychunk, 16)
1795: 			for i := range chunks {
1796: 				chunks[i] = &SrvCopychunk{
1797: 					SourceOffset: off + int64(i)*maxChunkSize,
1798: 					TargetOffset: woff + int64(i)*maxChunkSize,
1799: 					Length:       maxChunkSize,
1800: 				}
1801: 			}
1802: 
1803: 			remains -= maxTotalSize
1804: 		}
1805: 
1806: 		scc := &SrvCopychunkCopy{
1807: 			Chunks: chunks,
1808: 		}
1809: 
1810: 		copy(scc.SourceKey[:], sr.ResumeKey())
1811: 
1812: 		cReq := &IoctlRequest{
1813: 			CtlCode:           FSCTL_SRV_COPYCHUNK,
1814: 			OutputOffset:      0,
1815: 			OutputCount:       0,
1816: 			MaxInputResponse:  0,
1817: 			MaxOutputResponse: 24,
1818: 			Flags:             SMB2_0_IOCTL_IS_FSCTL,
1819: 			Input:             scc,
1820: 		}
1821: 
1822: 		output, err = wf.ioctl(cReq)
1823: 		if err != nil {
1824: 			return true, -1, &os.LinkError{Op: "copy", Old: f.name, New: wf.name, Err: err}
1825: 		}
1826: 
1827: 		c := SrvCopychunkResponseDecoder(output)
1828: 		if c.IsInvalid() {
1829: 			return true, -1, &os.LinkError{Op: "copy", Old: f.name, New: wf.name, Err: &InvalidResponseError{"broken srv copy chunk response format"}}
1830: 		}
1831: 
1832: 		n += int64(c.TotalBytesWritten())
1833: 
1834: 		if remains == 0 {
1835: 			return true, n, nil
1836: 		}
1837: 	}
1838: }
