1848: 
1849: 		maxBufferSize := f.maxReadSize()
1850: 		if maxWriteSize := f.maxWriteSize(); maxWriteSize < maxBufferSize {
1851: 			maxBufferSize = maxWriteSize
1852: 		}
1853: 
1854: 		return copyBuffer(r, f, make([]byte, maxBufferSize))
1855: 	}
