36: 		_, err := rand.Read(req.ClientGuid[:])
37: 		if err != nil {
38: 			return nil, &InternalError{err.Error()}
39: 		}
40: 	} else {
41: 		req.ClientGuid = n.ClientGuid
42: 	}
