44: 	if n.SpecifiedDialect != UnknownSMB {
45: 		req.Dialects = []uint16{n.SpecifiedDialect}
46: 
47: 		switch n.SpecifiedDialect {
48: 		case SMB202:
49: 		case SMB210:
50: 		case SMB300:
51: 		case SMB302:
52: 		case SMB311:
53: 			hc := &HashContext{
54: 				HashAlgorithms: clientHashAlgorithms,
55: 				HashSalt:       make([]byte, 32),
56: 			}
57: 			if _, err := rand.Read(hc.HashSalt); err != nil {
58: 				return nil, &InternalError{err.Error()}
59: 			}
60: 
61: 			cc := &CipherContext{
62: 				Ciphers: clientCiphers,
63: 			}
64: 
65: 			req.Contexts = append(req.Contexts, hc, cc)
66: 		default:
67: 			return nil, &InternalError{"unsupported dialect specified"}
68: 		}
69: 	} else {
70: 		req.Dialects = clientDialects
71: 
