73: 			HashAlgorithms: clientHashAlgorithms,
74: 			HashSalt:       make([]byte, 32),
75: 		}
76: 		if _, err := rand.Read(hc.HashSalt); err != nil {
77: 			return nil, &InternalError{err.Error()}
78: 		}
79: 
80: 		cc := &CipherContext{
81: 			Ciphers: clientCiphers,
82: 		}
83: 
84: 		req.Contexts = append(req.Contexts, hc, cc)
85: 	}
