90: func (n *Negotiator) negotiate(t transport, a *account, ctx context.Context) (*conn, error) {
91: 	conn := &conn{
92: 		t:                   t,
93: 		outstandingRequests: newOutstandingRequests(),
94: 		account:             a,
95: 		rdone:               make(chan struct{}, 1),
96: 		wdone:               make(chan struct{}, 1),
97: 		write:               make(chan []byte, 1),
98: 		werr:                make(chan error, 1),
99: 	}
100: 
101: 	go conn.runSender()
102: 	go conn.runReciever()
103: 
104: retry:
105: 	req, err := n.makeRequest()
106: 	if err != nil {
107: 		return nil, err
108: 	}
109: 
110: 	req.CreditCharge = 1
111: 
112: 	rr, err := conn.send(req, ctx)
113: 	if err != nil {
114: 		return nil, err
115: 	}
116: 
117: 	pkt, err := conn.recv(rr)
118: 	if err != nil {
119: 		return nil, err
120: 	}
121: 
122: 	res, err := accept(SMB2_NEGOTIATE, pkt)
123: 	if err != nil {
124: 		return nil, err
125: 	}
126: 
127: 	r := NegotiateResponseDecoder(res)
128: 	if r.IsInvalid() {
129: 		return nil, &InvalidResponseError{"broken negotiate response format"}
130: 	}
131: 
132: 	if r.DialectRevision() == SMB2 {
133: 		n.SpecifiedDialect = SMB210
134: 
135: 		goto retry
136: 	}
137: 
138: 	if n.SpecifiedDialect != UnknownSMB && n.SpecifiedDialect != r.DialectRevision() {
139: 		return nil, &InvalidResponseError{"unexpected dialect returned"}
140: 	}
141: 
142: 	conn.requireSigning = n.RequireMessageSigning || r.SecurityMode()&SMB2_NEGOTIATE_SIGNING_REQUIRED != 0
143: 	conn.capabilities = clientCapabilities & r.Capabilities()
144: 	conn.dialect = r.DialectRevision()
145: 	conn.maxTransactSize = r.MaxTransactSize()
146: 	conn.maxReadSize = r.MaxReadSize()
147: 	conn.maxWriteSize = r.MaxWriteSize()
148: 	conn.sequenceWindow = 1
149: 
150: 	// conn.gssNegotiateToken = r.SecurityBuffer()
151: 	// conn.clientGuid = n.ClientGuid
152: 	// copy(conn.serverGuid[:], r.ServerGuid())
153: 
154: 	if conn.dialect != SMB311 {
155: 		return conn, nil
156: 	}
157: 
158: 	// handle context for SMB311
159: 	list := r.NegotiateContextList()
160: 	for count := r.NegotiateContextCount(); count > 0; count-- {
161: 		ctx := NegotiateContextDecoder(list)
162: 		if ctx.IsInvalid() {
163: 			return nil, &InvalidResponseError{"broken negotiate context format"}
164: 		}
165: 
166: 		switch ctx.ContextType() {
167: 		case SMB2_PREAUTH_INTEGRITY_CAPABILITIES:
168: 			d := HashContextDataDecoder(ctx.Data())
169: 			if d.IsInvalid() {
170: 				return nil, &InvalidResponseError{"broken hash context data format"}
171: 			}
172: 
173: 			algs := d.HashAlgorithms()
174: 
175: 			if len(algs) != 1 {
176: 				return nil, &InvalidResponseError{"multiple hash algorithms"}
177: 			}
178: 
179: 			conn.preauthIntegrityHashId = algs[0]
180: 
181: 			switch conn.preauthIntegrityHashId {
182: 			case SHA512:
183: 				h := sha512.New()
184: 				h.Write(conn.preauthIntegrityHashValue[:])
185: 				h.Write(rr.pkt)
186: 				h.Sum(conn.preauthIntegrityHashValue[:0])
187: 
188: 				h.Reset()
189: 				h.Write(conn.preauthIntegrityHashValue[:])
190: 				h.Write(pkt)
191: 				h.Sum(conn.preauthIntegrityHashValue[:0])
192: 			default:
193: 				return nil, &InvalidResponseError{"unknown hash algorithm"}
194: 			}
195: 		case SMB2_ENCRYPTION_CAPABILITIES:
196: 			d := CipherContextDataDecoder(ctx.Data())
197: 			if d.IsInvalid() {
198: 				return nil, &InvalidResponseError{"broken cipher context data format"}
199: 			}
200: 
201: 			ciphs := d.Ciphers()
202: 
203: 			if len(ciphs) != 1 {
204: 				return nil, &InvalidResponseError{"multiple cipher algorithms"}
205: 			}
206: 
207: 			conn.cipherId = ciphs[0]
208: 
209: 			switch conn.cipherId {
210: 			case AES128CCM:
211: 			case AES128GCM:
212: 			default:
213: 				return nil, &InvalidResponseError{"unknown cipher algorithm"}
214: 			}
215: 		default:
216: 			// skip unsupported context
217: 		}
218: 
219: 		off := ctx.Next()
220: 
221: 		if len(list) < off {
222: 			list = nil
223: 		} else {
224: 			list = list[off:]
225: 		}
226: 	}
227: 
228: 	return conn, nil
229: }
